                <div x-show="previewHtml" class="mx-auto" :style="spaceStyle"><div class="bg-white shadow-lg" :style="pageStyle"><iframe title="Sanitized document preview" sandbox="" class="h-full w-full border-0" :srcdoc="previewHtml"></iframe></div></div>
