<script>
function documentDesigner(template, paperSizes) {
    const defaults={top:14,right:12,bottom:14,left:12}, sizes={letter:[215.9,279.4],legal:[215.9,355.6],a4:[210,297],a3:[297,420],tabloid:[279.4,431.8]};
    const safeTemplate=JSON.parse(JSON.stringify(template));safeTemplate.margins??={top:null,right:null,bottom:null,left:null};
    return {
        form:safeTemplate, originalDefault:!!template.is_default, originalType:template.type, blocksData:safeTemplate.blocks||[], blocksText:JSON.stringify(safeTemplate.blocks||[],null,2), blocksValid:true, zoom:75, newBlockType:'heading', previewHtml:'',previewError:'',previewLoading:false,compileError:'',compiling:false,timer:null,requestId:0,
        init(){this.$watch('form',()=>this.schedulePreview(),{deep:true});this.$watch('blocksText',(value)=>{try{const parsed=JSON.parse(value);if(Array.isArray(parsed)){this.blocksValid=true;this.blocksData=parsed;this.blocksData.forEach(b=>{b.props??={};b.style??={};});}else this.blocksValid=false;}catch(_){this.blocksValid=false;}this.schedulePreview();});this.blocksData.forEach(b=>{b.props??={};b.style??={};});this.schedulePreview();},
        get blocks(){return this.blocksValid?this.blocksData:null;},
        get dimensions(){const d=sizes[this.form.paper_size]||sizes.letter;return this.form.orientation==='landscape'?[d[1],d[0]]:d;},
        get pageStyle(){return {width:this.dimensions[0]+'mm',height:this.dimensions[1]+'mm',padding:['top','right','bottom','left'].map((s)=>`${this.form.margins?.[s]??defaults[s]}mm`).join(' '),transform:`scale(${this.zoom/100})`,transformOrigin:'top left'};},
        get spaceStyle(){return {width:(this.dimensions[0]*this.zoom/100)+'mm',height:(this.dimensions[1]*this.zoom/100)+'mm'};},
        schedulePreview(){clearTimeout(this.timer);const id=++this.requestId;this.previewLoading=true;this.timer=setTimeout(()=>this.preview(id),500);},
        async preview(id){const blocks=this.blocks;if(!blocks){this.previewError='Blocks must be a valid JSON array.';this.previewLoading=false;return;}try{const d={type:this.form.type,entity_type:this.form.entity_type,editor:this.form.editor,blocks,html:this.form.html||'',css:this.form.css||'',paper_size:this.form.paper_size,orientation:this.form.orientation,margins:this.form.margins,watermark:this.form.watermark};const r=await fetch('{{ route('documents.templates.preview') }}',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify(d)});const out=await r.json();if(id!==this.requestId)return;if(!r.ok)throw new Error(out.message||'The request failed. Check your connection and try again.');if(out.error){this.previewError=(out.error.line?'Line '+out.error.line+': ':'')+out.error.message;this.previewHtml='';}else{this.previewError='';this.previewHtml=(out.html||'').replace('<head>',`<head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data: ${location.origin}">`);}}catch(e){if(id===this.requestId){this.previewHtml='';this.previewError=e.message||'The request failed. Check your connection and try again.';}}finally{if(id===this.requestId)this.previewLoading=false;}},
        syncBlocks(){this.blocksData=this.blocksData.map(b=>{b.props??={};b.style??={};return b;});this.blocksText=JSON.stringify(this.blocksData,null,2);this.schedulePreview();},
        blockRows(block){const key={fields:'fields',items_table:'columns',totals:'rows',signature:'lines'}[block.type];if(!key)return[];block.props[key]??=[];return block.props[key];},
        addRow(block){const key={fields:'fields',items_table:'columns',totals:'rows',signature:'lines'}[block.type];block.props[key]??=[];block.props[key].push(block.type==='signature'?{label:''}:{label:'',value:''});this.syncBlocks();},
        removeRow(block,index){const key={fields:'fields',items_table:'columns',totals:'rows',signature:'lines'}[block.type];block.props[key].splice(index,1);this.syncBlocks();},
        updateNestedBlocks(block,index,text){try{const parsed=JSON.parse(text);if(!Array.isArray(parsed))throw new Error();block.props.columns[index].blocks=parsed;this.syncBlocks();}catch(_){}},
        updateConditionalBlocks(block,text){try{const parsed=JSON.parse(text);if(!Array.isArray(parsed))throw new Error();block.props.blocks=parsed;this.syncBlocks();}catch(_){}},
        addBlock(){if(!this.blocks){this.compileError='Blocks must be a valid JSON array before adding a block.';return;}const defaultsByType={heading:{text:'',level:2},text:{html:'<p></p>'},image:{src:'',alt:''},fields:{columns:2,fields:[]},items_table:{source:'items',columns:[{label:'Item',value:'item.name'}]},totals:{rows:[]},signature:{lines:[{label:'Signature'}]},spacer:{height:16},columns:{columns:[{width:'50%',blocks:[]},{width:'50%',blocks:[]}]},conditional:{condition:'true',blocks:[]},html:{html:''}};this.blocksData.push({id:'b'+Date.now().toString(36),type:this.newBlockType,props:defaultsByType[this.newBlockType]||{},style:{}});this.syncBlocks();},
        moveBlock(index,direction){const b=this.blocks;const target=index+direction;if(target<0||target>=b.length)return;const item=b.splice(index,1)[0];b.splice(target,0,item);this.syncBlocks();},
        removeBlock(index){this.blocks.splice(index,1);this.syncBlocks();},
        setEditor(mode){if(mode===this.form.editor)return;if(mode==='visual'&&this.form.html&&!confirm('Saving in visual mode removes the saved HTML. Your blocks will be kept. Continue?'))return;if(mode==='code'&&!this.form.html&&!confirm('The HTML editor is empty. Compile blocks to HTML if you want to use this visual layout in code mode. Continue with empty HTML?'))return;this.form.editor=mode;},
        async compile(){if(this.form.html&&!confirm('Replace the current HTML with the compiled blocks?'))return;this.compiling=true;this.compileError='';const blocks=this.blocks;if(!blocks){this.compileError='Blocks must be a valid JSON array.';this.compiling=false;return;}try{const r=await fetch('{{ route('documents.templates.compile') }}',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({blocks})});const d=await r.json();if(!r.ok)throw new Error(d.message||'The request failed.');if(d.error)this.compileError=(d.error.line?'Line '+d.error.line+': ':'')+d.error.message;else{this.form.html=d.source||'';this.form.editor='code';}}catch(e){this.compileError=e.message||'The request failed.';}finally{this.compiling=false;}},
        append(data,key,value){if(value===null||value===undefined){data.append(key,'');return;}if(Array.isArray(value)){value.forEach((v,i)=>this.append(data,`${key}[${i}]`,v));return;}if(typeof value==='object'){Object.entries(value).forEach(([k,v])=>this.append(data,key?`${key}[${k}]`:k,v));return;}data.append(key,String(value));},
        submit(event){const blocks=this.blocks;if(!blocks){this.compileError='Blocks must be a valid JSON array.';return;}if(this.form.editor==='visual'&&this.form.html&&!confirm('Saving in visual mode removes the saved HTML. Continue?'))return;const form=event.currentTarget;form.querySelectorAll('[data-generated-block]').forEach((el)=>el.remove());const data=new FormData();this.append(data,'blocks',blocks);for(const [k,v] of data.entries()){const input=document.createElement('input');input.type='hidden';input.name=k;input.value=v;input.dataset.generatedBlock='1';form.append(input);}form.submit();}
    };
}
</script>
@endcomponent
